async function inspectPages() {
  const pages = figma.root.children;
  const result = {};

  for (const page of pages) {
    await figma.setCurrentPageAsync(page);
    result[page.name] = {
      id: page.id,
      children: page.children.map(c => ({
        id: c.id,
        name: c.name,
        type: c.type,
        x: c.x,
        y: c.y,
        width: c.width,
        height: c.height
      }))
    };
  }

  // Helper to dump text nodes from a page
  async function getTextContents(pageName) {
    const page = pages.find(p => p.name.includes(pageName));
    if (!page) return [];
    await figma.setCurrentPageAsync(page);
    const texts = page.findAll(n => n.type === 'TEXT');
    return texts.map(t => ({ id: t.id, name: t.name, characters: t.characters, parent: t.parent.name }));
  }

  const startHereTexts = await getTextContents('00 · Start Here');
  const foundationsTexts = await getTextContents('01 · Foundations');

  return {
    pagesSummary: result,
    startHereTexts,
    foundationsTexts
  };
}

return await inspectPages();

async function inspectComponentsAndMedia() {
  const componentsPage = figma.root.children.find(p => p.name.includes('02 · Components'));
  const mediaPage = figma.root.children.find(p => p.name.includes('04 · Media'));

  let components = [];
  if (componentsPage) {
    await figma.setCurrentPageAsync(componentsPage);
    components = componentsPage.findAll().map(n => ({
      id: n.id,
      name: n.name,
      type: n.type
    }));
  }

  let media = [];
  if (mediaPage) {
    await figma.setCurrentPageAsync(mediaPage);
    media = mediaPage.findAll(n => n.parent && n.parent.name === 'Media' || n.type === 'COMPONENT' || n.type === 'FRAME' || n.type === 'GROUP' || n.type === 'INSTANCE').map(n => ({
      id: n.id,
      name: n.name,
      type: n.type,
      parent: n.parent ? n.parent.name : null
    }));
  }

  return { components, media };
}

return await inspectComponentsAndMedia();

async function mapMediaAndComponents() {
  const mediaPage = figma.root.children.find(p => p.name.includes('04 · Media'));
  const componentsPage = figma.root.children.find(p => p.name.includes('02 · Components'));

  const assetMap = {};

  if (mediaPage) {
    await figma.setCurrentPageAsync(mediaPage);
    const nodes = mediaPage.findAll(n => n.type === 'COMPONENT' || n.type === 'FRAME' || n.type === 'GROUP' || n.type === 'COMPONENT_SET');
    for (const node of nodes) {
      assetMap[node.name] = { id: node.id, type: node.type, page: '04 · Media' };
    }
  }

  if (componentsPage) {
    await figma.setCurrentPageAsync(componentsPage);
    const nodes = componentsPage.findAll(n => n.type === 'COMPONENT' || n.type === 'FRAME' || n.type === 'GROUP' || n.type === 'COMPONENT_SET');
    for (const node of nodes) {
      assetMap[node.name] = { id: node.id, type: node.type, page: '02 · Components' };
    }
  }

  return assetMap;
}

return await mapMediaAndComponents();

