  await figma.loadFontAsync({ family: "Montserrat", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "Montserrat", style: "Bold" });

  const workspace = figma.root.children.find(p => p.name.includes('03 · Workspace'));
  await figma.setCurrentPageAsync(workspace);

  // Helper to clone media component instance
  function createInstanceByName(name, parent) {
    const mediaPage = figma.root.children.find(p => p.name.includes('04 · Media'));
    const comp = mediaPage.findOne(n => n.name === name && (n.type === 'COMPONENT' || n.type === 'COMPONENT_SET'));
    if (comp) {
      const inst = comp.createInstance();
      parent.appendChild(inst);
      return inst;
    }
    return null;
  }

  function createStatusAndHome(frame) {
    const compPage = figma.root.children.find(p => p.name.includes('02 · Components'));
    const sbComp = compPage.findOne(n => n.name === 'Status Bar');
    const hiComp = compPage.findOne(n => n.name === 'Home Indicator');
    if (sbComp) {
      const sb = sbComp.createInstance();
      sb.x = 0; sb.y = 0;
      frame.appendChild(sb);
    }
    if (hiComp) {
      const hi = hiComp.createInstance();
      hi.x = 0; hi.y = 796;
      frame.appendChild(hi);
    }
  }

  // 1. 01_Splash
  const f1 = figma.createFrame();
  f1.name = '01_Splash';
  f1.resize(375, 812);
  f1.x = 0; f1.y = 0;
  f1.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
  createStatusAndHome(f1);

  const logo1 = createInstanceByName('Stylish_Logo', f1);
  if (logo1) {
    logo1.x = (375 - logo1.width) / 2;
    logo1.y = (812 - logo1.height) / 2;
  }

  // Helper for onboarding 2, 3, 4
  function createOnboardingScreen(name, x, step, titleText, bodyText, mediaName, prevLink, nextLink, isLast) {
    const frame = figma.createFrame();
    frame.name = name;
    frame.resize(375, 812);
    frame.x = x; frame.y = 0;
    frame.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    createStatusAndHome(frame);

    // Top Header bar: Step count (1/3) and Skip
    const topBar = figma.createFrame();
    topBar.name = 'TopBar';
    topBar.resize(343, 40);
    topBar.x = 16; topBar.y = 54;
    topBar.fills = [];
    frame.appendChild(topBar);

    const stepTxt = figma.createText();
    stepTxt.fontName = { family: "Montserrat", style: "Semi Bold" };
    stepTxt.fontSize = 18;
    stepTxt.characters = `${step}/3`;
    stepTxt.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
    stepTxt.x = 0; stepTxt.y = 8;
    topBar.appendChild(stepTxt);

    const skipTxt = figma.createText();
    skipTxt.name = 'Skip';
    skipTxt.fontName = { family: "Montserrat", style: "Semi Bold" };
    skipTxt.fontSize = 18;
    skipTxt.characters = 'Skip';
    skipTxt.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
    skipTxt.x = 343 - skipTxt.width; skipTxt.y = 8;
    topBar.appendChild(skipTxt);

    // Media
    const mediaInst = createInstanceByName(mediaName, frame);
    if (mediaInst) {
      mediaInst.x = (375 - mediaInst.width) / 2;
      mediaInst.y = 120;
    }

    // Title
    const title = figma.createText();
    title.fontName = { family: "Montserrat", style: "Bold" };
    title.fontSize = 24;
    title.characters = titleText;
    title.textAlignHorizontal = 'CENTER';
    title.resize(315, title.height);
    title.x = 30; title.y = 440;
    title.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
    frame.appendChild(title);

    // Body
    const body = figma.createText();
    body.fontName = { family: "Montserrat", style: "Regular" };
    body.fontSize = 14;
    body.characters = bodyText;
    body.textAlignHorizontal = 'CENTER';
    body.resize(315, 60);
    body.x = 30; body.y = 480;
    body.fills = [{ type: 'SOLID', color: { r: 0.5, g: 0.5, b: 0.5 } }];
    frame.appendChild(body);

    // Indicator dots
    const dots = figma.createFrame();
    dots.name = 'Pagination';
    dots.resize(60, 10);
    dots.x = (375 - 60) / 2; dots.y = 570;
    dots.fills = [];
    frame.appendChild(dots);

    for (let i = 1; i <= 3; i++) {
      const dot = figma.createRectangle();
      if (i === step) {
        dot.resize(35, 10);
        dot.cornerRadius = 5;
        dot.fills = [{ type: 'SOLID', color: { r: 0.09, g: 0.09, b: 0.09 } }];
      } else {
        dot.resize(10, 10);
        dot.cornerRadius = 5;
        dot.fills = [{ type: 'SOLID', color: { r: 0.8, g: 0.8, b: 0.8 } }];
      }
      dot.x = (i > step ? (i - 1) * 15 + 25 : (i - 1) * 15);
      dots.appendChild(dot);
    }

    // Bottom Navigation (Prev / Next or Get Started)
    const bottomNav = figma.createFrame();
    bottomNav.name = 'BottomNav';
    bottomNav.resize(343, 50);
    bottomNav.x = 16; bottomNav.y = 720;
    bottomNav.fills = [];
    frame.appendChild(bottomNav);

    if (step > 1) {
      const prevTxt = figma.createText();
      prevTxt.name = 'Prev';
      prevTxt.fontName = { family: "Montserrat", style: "Semi Bold" };
      prevTxt.fontSize = 18;
      prevTxt.characters = 'Prev';
      prevTxt.fills = [{ type: 'SOLID', color: { r: 0.77, g: 0.77, b: 0.77 } }];
      prevTxt.x = 0; prevTxt.y = 14;
      bottomNav.appendChild(prevTxt);
    }

    const nextBtn = figma.createText();
    nextBtn.name = isLast ? 'Get Started' : 'Next';
    nextBtn.fontName = { family: "Montserrat", style: "Semi Bold" };
    nextBtn.fontSize = 18;
    nextBtn.characters = isLast ? 'Get Started' : 'Next';
    nextBtn.fills = [{ type: 'SOLID', color: { r: 0.97, g: 0.22, b: 0.35 } }]; // #F83758
    nextBtn.x = 343 - nextBtn.width; nextBtn.y = 14;
    bottomNav.appendChild(nextBtn);

    return frame;
  }

  // 02_Onboarding_Choose_Products
  createOnboardingScreen(
    '02_Onboarding_Choose_Products', 420, 1,
    'Choose Products',
    'Browse thousands of products across fashion, beauty, electronics and more.',
    'Onboarding_Choose_Products', null, '03_Onboarding_Make_Payment', false
