  // 03_Onboarding_Make_Payment
  createOnboardingScreen(
    '03_Onboarding_Make_Payment', 840, 2,
    'Make Payment',
    'Pay securely with your saved cards, PayPal or Apple Pay.',
    'Onboarding_Make_Payment', '02_Onboarding_Choose_Products', '04_Onboarding_Get_Your_Order', false
