    'Track your order until it arrives at your door.',
    'Onboarding_Get_Your_Order', '03_Onboarding_Make_Payment', '05_Sign_In', true
  );

  return "Onboarding screens 01 to 04 created successfully";
}

return await buildOnboarding();

