async function addPrototypeInteractions() {
  const workspace = figma.root.children.find(p => p.name.includes('03 · Workspace'));
  await figma.setCurrentPageAsync(workspace);

  const framesMap = {};
  workspace.children.forEach(c => {
    framesMap[c.name] = c;
  });

  function linkNodeToFrame(fromNode, targetFrameName, triggerType = 'ON_CLICK') {
    if (!fromNode || !framesMap[targetFrameName]) return;
    try {
      fromNode.reactions = [
        {
          trigger: { type: triggerType },
          action: {
            type: 'NODE',
            destinationId: framesMap[targetFrameName].id,
            navigation: 'NAVIGATE',
            transition: null
          }
        }
      ];
    } catch (e) {
      // log or ignore if API level doesn't support reactions mutation directly
    }
  }

  // 1. 01_Splash -> auto-advance or tap -> 02_Onboarding_Choose_Products
  if (framesMap['01_Splash']) {
    linkNodeToFrame(framesMap['01_Splash'], '02_Onboarding_Choose_Products', 'ON_CLICK');
  }

  // 2. 02_Onboarding_Choose_Products
  if (framesMap['02_Onboarding_Choose_Products']) {
    const f = framesMap['02_Onboarding_Choose_Products'];
    const next = f.findOne(n => n.name === 'Next');
    const skip = f.findOne(n => n.name === 'Skip');
    linkNodeToFrame(next, '03_Onboarding_Make_Payment');
    linkNodeToFrame(skip, '05_Sign_In');
  }

  // 3. 03_Onboarding_Make_Payment
  if (framesMap['03_Onboarding_Make_Payment']) {
    const f = framesMap['03_Onboarding_Make_Payment'];
    const prev = f.findOne(n => n.name === 'Prev');
    const next = f.findOne(n => n.name === 'Next');
    const skip = f.findOne(n => n.name === 'Skip');
    linkNodeToFrame(prev, '02_Onboarding_Choose_Products');
    linkNodeToFrame(next, '04_Onboarding_Get_Your_Order');
    linkNodeToFrame(skip, '05_Sign_In');
  }

  // 4. 04_Onboarding_Get_Your_Order
  if (framesMap['04_Onboarding_Get_Your_Order']) {
    const f = framesMap['04_Onboarding_Get_Your_Order'];
    const prev = f.findOne(n => n.name === 'Prev');
    const gs = f.findOne(n => n.name === 'Get Started');
    const skip = f.findOne(n => n.name === 'Skip');
    linkNodeToFrame(prev, '03_Onboarding_Make_Payment');
    linkNodeToFrame(gs, '05_Sign_In');
    linkNodeToFrame(skip, '05_Sign_In');
  }

  // 5. 05_Sign_In
  if (framesMap['05_Sign_In']) {
    const f = framesMap['05_Sign_In'];
    const login = f.findOne(n => n.type === 'FRAME' && n.children.some(c => c.characters === 'Login'));
    const fp = f.findOne(n => n.name === 'Forgot Password?');
    const su = f.findOne(n => n.name === 'Create An Account Sign Up');
    linkNodeToFrame(login, '08_Get_Started');
    linkNodeToFrame(fp, '07_Forgot_Password');
    linkNodeToFrame(su, '06_Sign_Up');
  }

  // 6. 06_Sign_Up
  if (framesMap['06_Sign_Up']) {
    const f = framesMap['06_Sign_Up'];
    const createAcc = f.findOne(n => n.type === 'FRAME' && n.children.some(c => c.characters === 'Create Account'));
    const loginLink = f.findOne(n => n.name === 'I Already Have an Account Login');
    linkNodeToFrame(createAcc, '08_Get_Started');
    linkNodeToFrame(loginLink, '05_Sign_In');
  }

  // 7. 07_Forgot_Password
  if (framesMap['07_Forgot_Password']) {
    const f = framesMap['07_Forgot_Password'];
    const submit = f.findOne(n => n.type === 'FRAME' && n.children.some(c => c.characters === 'Submit'));
    linkNodeToFrame(submit, '05_Sign_In');
  }

  // 8. 08_Get_Started
  if (framesMap['08_Get_Started']) {
    const f = framesMap['08_Get_Started'];
    const gs = f.findOne(n => n.type === 'FRAME' && n.children.some(c => c.characters === 'Get Started'));
    linkNodeToFrame(gs, '09_Home');
  }

  // 9. 09_Home
  if (framesMap['09_Home']) {
    const f = framesMap['09_Home'];
    const trendViewAll = f.findOne(n => n.parent && n.parent.name === 'Trending Products' && n.name === 'View all');
    const spon = f.findOne(n => n.name === 'Sponsored');
    linkNodeToFrame(trendViewAll, '10_Product_List');
    linkNodeToFrame(spon, '11_Product_Detail');
  }

  // 11. 11_Product_Detail
  if (framesMap['11_Product_Detail']) {
    const f = framesMap['11_Product_Detail'];
    const back = f.findOne(n => n.name === 'back');
    const goToCart = f.findOne(n => n.name === 'Go to cart');
    linkNodeToFrame(back, '09_Home');
    linkNodeToFrame(goToCart, '12_Shopping_Bag');
  }

  // 12. 12_Shopping_Bag
  if (framesMap['12_Shopping_Bag']) {
    const f = framesMap['12_Shopping_Bag'];
    const back = f.findOne(n => n.name === 'back');
    const proc = f.findOne(n => n.name === 'Proceed to Payment');
    linkNodeToFrame(back, '11_Product_Detail');
    linkNodeToFrame(proc, '13_Payment');
  }

  // 13. 13_Payment
  if (framesMap['13_Payment']) {
    const f = framesMap['13_Payment'];
    const back = f.findOne(n => n.name === 'back');
    const cont = f.findOne(n => n.name === 'Continue');
    linkNodeToFrame(back, '12_Shopping_Bag');
    linkNodeToFrame(cont, '14_Payment_Success_Overlay');
  }

  // 14. 14_Payment_Success_Overlay
  if (framesMap['14_Payment_Success_Overlay']) {
    const f = framesMap['14_Payment_Success_Overlay'];
    const dlg = f.findOne(n => n.name === 'Success Dialog');
    linkNodeToFrame(dlg, '09_Home');
  }

  // 15. 15_Profile
  if (framesMap['15_Profile']) {
    const f = framesMap['15_Profile'];
    const back = f.findOne(n => n.name === 'back');
    linkNodeToFrame(back, '09_Home');
  }

  // Tab navigation setup across screens with tabs (09, 10, 11, 13)
  ['09_Home', '10_Product_List', '11_Product_Detail', '13_Payment'].forEach(fName => {
    const f = framesMap[fName];
    if (f) {
      const tabHome = f.findOne(n => n.name === 'Tab_Home');
      const tabCart = f.findOne(n => n.name === 'Tab_Cart');
      const tabSetting = f.findOne(n => n.name === 'Tab_Setting');
      linkNodeToFrame(tabHome, '09_Home');
      linkNodeToFrame(tabCart, '12_Shopping_Bag');
      linkNodeToFrame(tabSetting, '15_Profile');
    }
  });

  return "Prototype links wired successfully";
}

return await addPrototypeInteractions();

async function verifyWorkspaceFrames() {
  const workspace = figma.root.children.find(p => p.name.includes('03 · Workspace'));
  await figma.setCurrentPageAsync(workspace);

  return workspace.children.map(c => ({
    id: c.id,
    name: c.name,
    width: c.width,
    height: c.height,
    childCount: c.children.length
  }));
}

return await verifyWorkspaceFrames();
